## posthog_current
import posthog from "posthog-js";
import { sanitizePostHogEvent, sanitizeReplayRequest } from "./analytics-privacy";

export const ANALYTICS_SCHEMA_VERSION = 2;

export function postHogGlobalProperties() {
	return {
		analytics_schema_version: ANALYTICS_SCHEMA_VERSION,
		app_version: String(import.meta.env.APP_VERSION ?? "dev"),
		app_surface: "web",
		build_environment: import.meta.env.MODE,
	};
}

function enabledByDefault(value: string | undefined): boolean {
	return value !== "false";
}

export function isPostHogEnabled() {
	return Boolean(import.meta.env.VITE_POSTHOG_PROJECT_TOKEN) && import.meta.env.VITE_POSTHOG_DISABLED !== "true";
}

export function initPostHog() {
	if (!isPostHogEnabled()) return null;
	const token = import.meta.env.VITE_POSTHOG_PROJECT_TOKEN;
	if (!token) return null;
	const sessionReplayEnabled = enabledByDefault(import.meta.env.VITE_POSTHOG_SESSION_REPLAY);
	posthog.init(token, {
		api_host: '/ingest',
		ui_host: import.meta.env.VITE_POSTHOG_HOST || 'https://us.posthog.com',
		defaults: "2026-05-30",
		capture_pageview: "history_change",
		capture_pageleave: true,
		autocapture: true,
		capture_heatmaps: true,
		capture_dead_clicks: true,
		capture_performance: {
			network_timing: sessionReplayEnabled,
			web_vitals: true,
		},
		disable_session_recording: !sessionReplayEnabled,
		session_recording: {
			maskAllInputs: true,
			maskTextSelector: "*",
			maskCapturedNetworkRequestFn: sanitizeReplayRequest,
		},
		mask_all_text: true,
		mask_all_element_attributes: true,
		mask_personal_data_properties: true,
		capture_exceptions: true,
		enable_recording_console_log: false,
		before_send: sanitizePostHogEvent,
		loaded: (client) => {
			client.register(postHogGlobalProperties());
			client.register_once({ first_seen_app_version: postHogGlobalProperties().app_version });
		},
		debug: import.meta.env.DEV,
	});
	return posthog;
}

export { posthog };

## analytics_privacy
import type { CaptureResult, Properties } from "posthog-js";

/**
 * Custom properties that can contain learner-authored or model-authored data.
 * Keating analytics are deliberately behavioral: content stays on the user's
 * device and with the model provider they selected.
 */
const PRIVATE_CONTENT_PROPERTIES = new Set([
	"args",
	"content",
	"input",
	"message",
	"messages",
	"output",
	"prompt_text",
	"response",
	"result",
	"sample_text",
	"tool_args",
	"tool_result",
	"topic",
	"$ai_input",
	"$ai_output_choices",
]);

const PRIVATE_ROUTE_PATTERNS: ReadonlyArray<[RegExp, string]> = [
	[/^\/s\/[^/]+/, "/s/:shareId"],
	[/^\/courses\/join\/[^/]+/, "/courses/join/:token"],
	[/^\/courses\/[^/]+/, "/courses/:courseId"],
	[/^\/usage\/evolution\/[^/]+/, "/usage/evolution/:evolutionId"],
];

export function analyticsPath(pathname: string): string {
	for (const [pattern, replacement] of PRIVATE_ROUTE_PATTERNS) {
		if (pattern.test(pathname)) return pathname.replace(pattern, replacement);
	}
	return pathname;
}

/** Remove query strings, hashes, share IDs, invite tokens, and course IDs. */
export function analyticsUrl(value: unknown): unknown {
	if (typeof value !== "string" || !value) return value;
	try {
		const url = new URL(value, "https://keating.invalid");
		url.pathname = analyticsPath(url.pathname);
		url.search = "";
		url.hash = "";
		return url.origin === "https://keating.invalid" ? url.pathname : url.toString();
	} catch {
		return value.split(/[?#]/, 1)[0];
	}
}

export function sanitizeAnalyticsProperties(properties: Properties): Properties {
	const sanitized: Properties = { ...properties };
	for (const key of PRIVATE_CONTENT_PROPERTIES) delete sanitized[key];

	for (const key of ["$current_url", "$referrer", "$pathname", "$prev_pageview_pathname"]) {
		if (key in sanitized) sanitized[key] = analyticsUrl(sanitized[key]);
	}

	return sanitized;
}

export function sanitizePostHogEvent(event: CaptureResult | null): CaptureResult | null {
	if (!event) return null;
	return {
		...event,
		properties: sanitizeAnalyticsProperties(event.properties ?? {}),
	};
}

export function sanitizeReplayRequest<T extends { name?: string }>(request: T): T {
	return {
		...request,
		...(request.name ? { name: String(analyticsUrl(request.name)) } : {}),
	};
}

